public class TimeSeries_clone_TriageGen2Test {

    @Test
    public void testCloneEmptySeries() throws CloneNotSupportedException {
        TimeSeries series = new TimeSeries("Test Series");

        // Act
        TimeSeries clonedSeries = (TimeSeries) series.clone();

        // Assert
        assertNotNull("Cloned series should not be null", clonedSeries);
        assertNotSame("Cloned series should be a different object", series, clonedSeries);
        assertEquals("Cloned series should have same name", series.getName(), clonedSeries.getName());
        assertEquals("Cloned empty series should have 0 items", 0, clonedSeries.getItemCount());
    }

