    @Test
    public void testCloneProperties() throws CloneNotSupportedException {
        TimeSeries series = new TimeSeries("Test Series");
        series.setDomainDescription("Domain Desc");
        series.setRangeDescription("Range Desc");
        series.setMaximumItemCount(100);

        TimeSeries clonedSeries = (TimeSeries) series.clone();

        assertEquals("Domain description should be copied", series.getDomainDescription(), clonedSeries.getDomainDescription());
        assertEquals("Range description should be copied", series.getRangeDescription(), clonedSeries.getRangeDescription());
        assertEquals("Maximum item count should be copied", series.getMaximumItemCount(), clonedSeries.getMaximumItemCount());
    }

    /**
     * This test specifically targets the branch where getItemCount() > 0
     * to ensure createCopy(0, getItemCount() - 1) is executed with valid indices.
     */
    @Test
    public void testCloneWithDataItems() throws CloneNotSupportedException {
        // Using a dummy class that extends RegularTimePeriod since it's abstract
        class TestPeriod extends RegularTimePeriod {
            private final int val;
            TestPeriod(int val) { this.val = val; }
            @Override public int getDaylightSavingsOffset() { return 0; }
            @Override public boolean isLeapYear(int year) { return false; }
            @Override public int getYear() { return 2023; }
            @Override public int getMonth() { return 1; }
            @Override public int getDay() { return val; }
            @Override public int getHour() { return 0; }
            @Override public int getMinute() { return 0; }
            @Override public int getSecond() { return 0; }
            @Override public boolean isLeapYear() { return false; }
            @Override public int getQuarter() { return 1; }
            @Override public int getWeekOfYear() { return 1; }
            @Override public int getRelativeDaylightSavingsOffset() { return 0; }
            @Override public boolean equals(Object obj) { return obj instanceof TestPeriod && ((TestPeriod)obj).val == val; }
            @Override public int hashCode() { return val; }
        }

        TimeSeries series = new TimeSeries("Data Series");
        series.add(new TestPeriod(1), 10.0);
        series.add(new TestPeriod(2), 20.0);

        TimeSeries clonedSeries = (TimeSeries) series.clone();

        assertEquals(2, clonedSeries.getItemCount());
        assertEquals(10.0, clonedSeries.getValue(0).doubleValue(), 0.001);
        assertEquals(20.0, clonedSeries.getValue(1).doubleValue(), 0.001);
        assertNotSame(series.getTimePeriod(0), clonedSeries.getTimePeriod(0));
    }
